#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, m;
    std::cin >> n >> m;
    std::vector<unsigned long> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    int split_point = n / 2;
    std::vector<unsigned long> part1, part2;

    // Generate all subset sums for the first half
    std::function<void(int, unsigned long)> create_sums1 = [&](int i, unsigned long total) {
        if (i == split_point) {
            part1.push_back(total);
        } else {
            create_sums1(i + 1, (total + a[i]) % m);
            create_sums1(i + 1, total);
        }
    };

    // Generate all subset sums for the second half
    std::function<void(int, unsigned long)> create_sums2 = [&](int i, unsigned long total) {
        if (i == n) {
            part2.push_back(total);
        } else {
            create_sums2(i + 1, (total + a[i]) % m);
            create_sums2(i + 1, total);
        }
    };

    create_sums1(0, 0);
    create_sums2(split_point, 0);

    unsigned long max_value = 0;

    // Remove duplicates and sort part1
    std::vector<unsigned long> sorted_part1 = part1;
    std::sort(sorted_part1.begin(), sorted_part1.end());
    auto last = std::unique(sorted_part1.begin(), sorted_part1.end());
    sorted_part1.erase(last, sorted_part1.end());

    for (auto val : part2) {
        auto it = std::lower_bound(sorted_part1.begin(), sorted_part1.end(), m - val);
        if (it != sorted_part1.begin()) {
            --it;
            unsigned long candidate_value = *it + val;
            if (candidate_value > max_value) {
                max_value = candidate_value;
            }
        }
    }

    std::cout << max_value << std::endl;
    return 0;
}
